-- Keep the existing employee-facing baseline aligned with the expanded names.
insert into public.role_permissions (role_id, permission_key)
select r.id, x.permission_key
from public.roles r
join (values
  ('operations_executive', 'admin.shipments.assigned.view'),
  ('operations_executive', 'admin.shipments.view'),
  ('operations_executive', 'admin.tracking.view'),
  ('operations_executive', 'admin.pickup.view'),
  ('operations_executive', 'admin.exceptions.view'),
  ('client_relationship_manager', 'admin.clients.view'),
  ('client_relationship_manager', 'admin.clients.kyc.view'),
  ('client_relationship_manager', 'admin.clients.activity.view'),
  ('support_executive', 'admin.tickets.view'),
  ('support_executive', 'admin.tickets.reply'),
  ('finance_executive', 'admin.billing.view'),
  ('finance_executive', 'admin.transactions.view')
) as x(role_code, permission_key) on x.role_code = r.role_code
where r.scope = 'employee'
  and exists (select 1 from public.permissions p where p.permission_key = x.permission_key and p.panel = 'admin')
on conflict do nothing;

